from lib import *
S = SS('w32')
steps = [
    step("加入一个组播组:对 239.255.42.99 做 IP_ADD_MEMBERSHIP 之后,netstat -g 里 en0 多了这一组,链路层地址是 01:00:5e:7f:2a:63——组播 IP 地址映射到以太网组播 MAC 的规则是 01:00:5e 加 IP 地址的低 23 位(第二个字节的最高位被清掉)。加入时线上抓到 IGMP 成员报告:IP 目的和组地址都是 239.255.42.99,以太网目的 MAC 就是 01:00:5e:7f:2a:63,IGMP 类型 0x16(IGMPv2 的成员报告),IP 头 24 字节(多出的 4 字节是 Router Alert 选项),TTL 1。共抓到 3 个 IGMP 报文,另外 2 个是系统自己的 224.0.0.251(mDNS 组)的报告。因为 IP 地址里有 5 位被丢掉,32 个不同的组播地址共用一个 MAC:224.127.42.99 与 239.255.42.99 映射到同一个 01:00:5e:7f:2a:63。", t=tl(S(1)), mark=lidx(S(1), '239.255.42.99 → 以太网组播 MAC', '组地址 = 239.255.42.99', '验证:224.127.42.99'), done=lidx(S(1), '加入前 netstat', '共 3 个 IGMP 报文'), b=bars([['IP 组播地址', 32, '32 位'], ['以太网组播 MAC(低位)', 23, '23 位'], ['被丢掉的位', 5, '5 位 → 32 个地址共用一个 MAC']], 32, mark=[2], done=[0, 1]), kv=KV([['MAC 映射', '01:00:5e + IP 的低 23 位'], ['239.255.42.99', '→ 01:00:5e:7f:2a:63'], ['224.127.42.99', '→ 同一个 MAC'], ['IGMP 报告', '类型 0x16,IP 头 24 字节(Router Alert),TTL 1']], ['MAC 映射'])),
    step("谁能收到:发送方往组播地址发一个数据报。IP_MULTICAST_LOOP 默认是 1:加入了组的接收方 1 收到,同一端口上另一个加入了组的接收方 2 也收到,只绑了 0.0.0.0 端口但没加入组的接收方没收到。把 IP_MULTICAST_LOOP 关成 0:本机上两个加入了组的接收方都收不到(别的机器仍然能收到,这里没有第二台机器可验证)。没有设置 IP_MULTICAST_IF 的发送方发同一个组,接收方 1 也能收到(出口按路由表选)。线上抓到的帧:以太网目的 MAC 01:00:5e:7f:2a:63,正是上面算出的组播 MAC,IP 目的 239.255.42.99,TTL 1。", t=tl(S(2)), mark=lidx(S(2), '默认(LOOP=1)', 'IP_MULTICAST_LOOP = 0'), done=lidx(S(2), 'IP_MULTICAST_LOOP 默认值', '没有设置 IP_MULTICAST_IF', '线上:以太网目的 MAC'), kv=KV([['加入了组', '收到(含同一台机器上的)'], ['没加入组', '收不到'], ['LOOP = 0', '本机上的接收方也收不到'], ['线上', '目的 MAC = 01:00:5e:7f:2a:63']], ['没加入组'])),
    step("TTL 范围:IP_MULTICAST_TTL 默认是 1,所以默认只在本网段;设成 1、4、32 后线上抓到的 TTL 分别是 1、4、32。传统约定:TTL 0 只在本机、1 本子网、<32 本站点或机构内、<64 本地区、<128 本大洲、<255 全球;组播路由器每转发一次 TTL 减 1,所以 TTL 同时是“传播半径”。224.0.0.0/24 是“本地链路”组播(路由器永远不转发):8 秒里抓到别的设备发往它的 IP 包 236 个,TTL 取值只有 1、254 和 255。", t=tl(S(3)), mark=lidx(S(3), '新套接字 IP_MULTICAST_TTL', '224.0.0.0/24 是'), done=lidx(S(3), '传统约定'), b=bars([['设成 1 · 线上 TTL', 1, '1'], ['设成 4 · 线上 TTL', 4, '4'], ['设成 32 · 线上 TTL', 32, '32']], 32, mark=[1, 2], done=[0]), kv=KV([['默认 TTL', '1:不出本网段'], ['设成 4 / 32', '线上 TTL = 4 / 32'], ['224.0.0.0/24', '本地链路,路由器永不转发'], ['8 秒里看到', '236 个包,TTL 为 1 / 254 / 255']], ['默认 TTL'])),
    step("出口接口:route get 239.255.42.99 的接口是 en0,标志含 MULTICAST 和 IFSCOPE。接收方在某个接口地址上加入、发送方用同一个接口地址发:en0 的地址 → 收到,lo0 的地址 127.0.0.1 → 也收到(所以在本机上可以用 lo0 测试组播)。但是接收方在 lo0 上加入、发送方从 en0 发:没收到——组播成员关系是按接口算的,在哪个接口加入就只收那个接口来的。", t=tl(S(4)), mark=lidx(S(4), '接收方在 lo0 上加入'), done=lidx(S(4), 'route get 239', '接收方在某个接口地址上加入'), kv=KV([['route get 组播地址', '接口 en0,标志 MULTICAST'], ['同一接口发和收', 'en0 / lo0 都能收到'], ['lo0 加入、从 en0 发', '收不到:成员关系按接口']], ['lo0 加入、从 en0 发'])),
    step("成员关系的数量与计数:一个套接字连续加入 400 个不同的组,全部成功,没有碰到每个套接字的上限(sysctl 里也没有 net.inet.ip.maxmemberships 这一项,更大数量没有试)。两个套接字加入同一个组 239.255.42.77:netstat 里该组的条目数始终是 1;关掉第一个套接字后条目还在(1),关掉第二个后才消失(0)——内核对同一个接口上的同一个组只记一个成员,按引用计数,最后一个套接字离开才真正退出。", t=tl(S(5)), mark=lidx(S(5), '一个套接字连续加入 400', '两个套接字加入同一个组'), done=lidx(S(5), '(sysctl 里没有'), b=bars([['一个套接字加入的组', 400, '400(全部成功)'], ['两个套接字加同一组 · 条目数', 1, '1'], ['关掉第二个后', 0, '0']], 400, mark=[1], done=[0, 2]), kv=KV([['单套接字', '400 个组全部成功,上限没找到'], ['同一个组两个套接字', 'netstat 里只有 1 条,引用计数'], ['最后一个离开', '才真正退出该组']], ['同一个组两个套接字'])),
]
A = mkartw('w32', 32, '网络协议,UDP,组播,IP_ADD_MEMBERSHIP,IGMP,IP_MULTICAST_TTL,真实验证,动画演示',
    '加入组播组后 netstat 里多出 01:00:5e 加 IP 低 23 位的链路层地址,线上发出 IGMPv2 报告;32 个组播地址共用一个 MAC;只有加入了组的套接字收得到,默认 TTL 是 1,LOOP=0 本机接收方也收不到;成员关系按接口、按引用计数。',
    '组播和广播有什么不同?加入一个组播组时线上发生了什么?组播的 TTL 为什么默认是 1,环回是怎么回事?这篇在本机 en0 和 lo0 上真的加入一个组,抓 IGMP 报告和组播帧,逐项验证成员关系、TTL 范围、回环和接口的规则。',
    [('01:00:5e:7f:2a:63', '239.255.42.99 对应的以太网组播 MAC:01:00:5e 加 IP 地址的低 23 位'), ('32 个', '共用同一个以太网组播 MAC 的不同 IP 组播地址数量(IP 里有 5 位被丢掉)'), ('TTL 1', '组播默认的 IP_MULTICAST_TTL:默认不会离开本网段')],
    [('加入组', '<p>IP_ADD_MEMBERSHIP 让网卡开始收对应的以太网组播 MAC 的帧,同时内核发出 IGMP 成员报告。netstat -g 能看到成员关系和 MAC。</p>'),
     ('谁能收', '<p>只有加入了组的套接字收得到(包括同一台机器上的其它加入者);关掉 IP_MULTICAST_LOOP 后同一台机器上的接收方就收不到自己发的包。</p>'),
     ('TTL 与范围', '<p>默认 TTL 是 1,只在本网段;TTL 越大传播半径越大;224.0.0.0/24 永远是本地链路。</p>'),
     ('按接口', '<p>成员关系属于接口:在 lo0 上加入就只收 lo0 来的组播,发送方用 IP_MULTICAST_IF 选出口。</p>'),
     ('计数', '<p>同一个接口上的同一个组只记一条成员关系,按引用计数,最后一个套接字离开才真正退出。</p>')],
    steps,
    [ENV_W + '。组播组使用的是私有管理范围 239.255.0.0/16 里的测试地址;同一台机器上没有第二台主机可以验证跨机器的接收,所以 LOOP=0 的效果只验证了本机内;第三节最后统计的是别人发往 224.0.0.0/24 的包,只记个数与 TTL',
     '没有验证:跨路由器的组播转发(PIM);一个套接字加入的组数量上限(试到 400 个仍没有上限);IGMP 查询触发的重复报告(见下一篇);Wi-Fi 接入点对组播的处理方式;IPv6 组播(MLD)的行为'],
    'UDP 组播')
